import {snowRadius} from './aurora-terrain.js';
import * as T from './vendor/three.module.js';
import {createTeddy} from './teddy.js';
export function createAuroraPublic({world,interior,player,pose}){
 let session=null,busy=false,joined=false,stopped=false,guests=[],self=null,spawned=false;const peers=new Map();
 async function api(body){const r=await fetch('/api/aurora/lodge',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':session.csrf,'X-Planet-Space':String(session.space)},body:JSON.stringify(body),keepalive:body.action==='leave',signal:AbortSignal.timeout(12000)});const v=await r.json();if(!r.ok){const error=Error(v.error||'暂时连接不到雪境');error.status=r.status;throw error};return v;}
 function paint(value){self=value.self;guests=value.guests||[];const own=guests.find(g=>g.id===self);interior.setOrder(own);
 if(own&&!spawned){spawned=true;if(own.appearance){player.design(own.appearance);player.outfit(own.outfit||'plain');interior.setAppearance(own.appearance,own.outfit)}const phi=(Number(own.id)||1)*2.39996,theta=.30,normal=new T.Vector3(Math.sin(theta)*Math.cos(phi),Math.cos(theta),Math.sin(theta)*Math.sin(phi));world.add(player.avatar);player.avatar.position.copy(normal).multiplyScalar(snowRadius(theta,phi)+.018);player.avatar.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),normal);player.seatTick(false,.1);player.legs.forEach(g=>g.rotation.x=0);}
 const live=new Set();for(const g of guests){if(g.id===self||!g.position||!g.quaternion)continue;live.add(g.id);let peer=peers.get(g.id);if(!peer){peer=createTeddy(world,g.avatar);peer.avatar.scale.setScalar(.63);if(g.appearance){peer.design(g.appearance);peer.outfit(g.outfit||'plain')}peers.set(g.id,peer)}const parent=g.room==='inside'?interior.group:world;if(peer.avatar.parent!==parent)parent.add(peer.avatar);peer.avatar.position.fromArray(g.position);peer.avatar.quaternion.fromArray(g.quaternion);peer.seatTick(g.seated,.1);peer.relax(true);}for(const [id,p] of peers)if(!live.has(id)){p.avatar.removeFromParent();peers.delete(id)}const count=document.querySelector('#aurora-count');if(count)count.textContent=guests.length+' 位访客';}
 async function sync(){if(!joined||busy||stopped||document.hidden)return;busy=true;try{paint(await api({action:'sync',...pose()}));}catch(e){if(e.status===409){try{paint(await api({action:'join',room:pose().room}));}catch{}}else console.warn('雪境连接暂时中断');}finally{busy=false}}
 const ready=(async()=>{let r;try{r=await fetch('/api/session',{credentials:'same-origin'});session=await r.json()}catch{session=null}if(!session?.authenticated){session=null;if(new URLSearchParams(location.search).has('embedded')&&window.parent!==window&&window.parent.PLANET_RUNTIME?.mode==='cloud')throw Error('请先登录再进入雪境');return;}paint(await api({action:'join',room:'outside'}));joined=true;player.setIdentity(session.avatars?.[session.actor]||0);interior.setIdentity(session.avatars?.[session.actor]||0);await sync();})();
 const timer=setInterval(sync,850);
 return {ready,sync,state:()=>({joined,self,visitors:guests.length}),async stop(){stopped=true;clearInterval(timer);if(joined)try{await api({action:'leave'})}catch{}for(const p of peers.values())p.avatar.removeFromParent();peers.clear()},peers};
}
